function context(){let text='';const opened=document.querySelector('.workspace-dialog[open]');if(opened&&typeof activeTask!=='undefined'&&activeTask){text=`${activeTask.domain==='physics'?'Физика':'Математика'}, ${activeTask.grade} класс. ${activeTask.title}\n${activeTask.originalQuestionText||activeTask.question}`}else if(document.querySelector('#computingSection')?.hidden===false){if(!document.querySelector('#cppPanel')?.hidden){const l=window.matclubCppCourse?.lessons.find(l=>l.id===window.matclubCpp?.state.id);if(l)text='C++: '+l.title+'\n'+l.task}else{text='Python: '+(document.querySelector('#pyLessonTitle')?.textContent||'')+'\n'+(document.querySelector('.py-exercise-head')?.textContent||'')}}else if(document.querySelector('#labSection')?.hidden===false){const e=window.matclubLabModels?.labs.find(e=>e.id===window.matclubLab?.state.id);if(e)text='Физическая лаборатория: '+e.title+'\n'+e.intro+'\n'+e.formula}else{const lesson=document.querySelector('.lesson-dialog[open]');if(lesson)text=lesson.querySelector('h2')?.textContent+'\n'+(lesson.querySelector('.lesson-intro')?.textContent||'')}return text.slice(0,3000)}
function describe(){const c=context();$('#aiContextLabel').textContent=$('#aiContext').checked?(c?'Контекст: '+c.split('\n')[0]:'Открытая задача не выбрана — можно задать любой учебный вопрос.'):'Контекст не прикладывается.'}
function formatted(target,text){
 const lines=text.split('\n');let pre=null,list=null;
 for(const line of lines){
  if(line.trim().startsWith('```')){list=null;if(pre){pre=null}else{pre=document.createElement('pre');pre.tabIndex=0;const code=document.createElement('code');pre.append(code);target.append(pre)}continue}
  if(pre){pre.firstChild.textContent+=line+'\n';continue}
  if(!line.trim()){list=null;continue}
  const item=line.match(/^\s*(?:[-*]|\d+[.)])\s+(.+)$/),heading=line.match(/^#{1,4}\s+(.+)$/);let el;
  if(item){const number=line.match(/^\s*(\d+)[.)]/),tag=number?'ol':'ul';if(!list||list.tagName.toLowerCase()!==tag){list=document.createElement(tag);if(number)list.start=Math.min(10000,Number(number[1]));target.append(list)}el=document.createElement('li');list.append(el)}else{list=null;el=document.createElement(heading?'h3':'p');target.append(el)}
  const content=item?item[1]:heading?heading[1]:line;
  for(const part of content.split(/(\*\*[^*]+\*\*|`[^`]+`)/g)){if(part.startsWith('**')&&part.endsWith('**')){const bold=document.createElement('strong');bold.textContent=part.slice(2,-2);el.append(bold)}else if(part.startsWith('`')&&part.endsWith('`')){const code=document.createElement('code');code.textContent=part.slice(1,-1);el.append(code)}else el.append(document.createTextNode(part))}
 }
}
function bubble(role,text){const div=document.createElement('div');div.className='ai-message ai-'+role;const label=document.createElement('b');label.textContent=role==='user'?'Ты':'Помощник';const p=document.createElement('div');p.className='ai-prose';if(role==='assistant')formatted(p,text);else p.textContent=text;div.append(label,p);
 if(role==='assistant'){const tools=document.createElement('div');tools.className='ai-message-tools';const copy=document.createElement('button');copy.type='button';copy.textContent='Копировать ответ';copy.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(text);$('#aiStatus').textContent='Ответ скопирован.'}catch{const range=document.createRange();range.selectNodeContents(p);const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);$('#aiStatus').textContent='Ответ выделен — выбери «Копировать».'}});tools.append(copy);div.append(tools)}
 const area=$('#aiMessages');area.append(div);if(role==='assistant'){area.scrollTop+=div.getBoundingClientRect().top-area.getBoundingClientRect().top-14;dialog.classList.add('ai-has-answer')}else area.scrollTop=area.scrollHeight;return div}
function setBusy(value){busy=value;$('#aiSend').disabled=value;$('#aiStop').hidden=!value;$('#aiClear').disabled=value;$('#aiInput').readOnly=value;dialog.setAttribute('aria-busy',String(value))}
async function send(event){event.preventDefault();if(busy)return;if(!signedIn()){askForAccount();return}const message=$('#aiInput').value.trim();if(!message)return;if(innerWidth<=767)$('#aiInput').blur();dialog.classList.add('ai-started');const ctx=$('#aiContext').checked?context():'';const node=bubble('user',message);setBusy(true);$('#aiStatus').textContent='Помощник думает…';controller=new AbortController();const timeout=setTimeout(()=>controller?.abort(),30000);try{const response=await fetch('/api/assistant',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({message,context:ctx,history:history.slice(-8)}),signal:controller.signal});let data;try{data=await response.json()}catch{throw Error('Сервис помощника пока недоступен.')}if(response.status===401){sessionRejected=true;askForAccount();throw Error('Сессия завершилась. Войди в аккаунт ещё раз.')}if(!response.ok){const wait=Number(response.headers?.get?.('retry-after'));throw Error((data.error||'Не удалось получить ответ.')+(Number.isFinite(wait)&&wait>0?' Повтори примерно через '+(wait>=3600?Math.ceil(wait/3600)+' ч.':Math.ceil(wait/60)+' мин.') :''));}if(typeof data.answer!=='string')throw Error('Модель вернула пустой ответ.');bubble('assistant',data.answer);history.push({role:'user',content:message},{role:'assistant',content:data.answer.slice(0,2000)});history=history.slice(-8);$('#aiInput').value='';$('#aiStatus').textContent='Ответ готов.'+(data.modelLabel?' · '+data.modelLabel:'')}catch(e){node.classList.add('ai-unsent');$('#aiStatus').textContent=e.name==='AbortError'?'Запрос остановлен. Вопрос сохранён в поле ввода.':e.message}finally{clearTimeout(timeout);controller=null;setBusy(false)}}
function host(){if(dialog.open)return;const others=[...document.querySelectorAll('dialog[open]')].filter(d=>d!==dialog);const target=others.at(-1)||document.body;if(launch.parentNode!==target){target.append(launch);requestAnimationFrame(restorePosition)}}
new MutationObserver(host).observe(document.body,{subtree:true,attributes:true,attributeFilter:['open']});
// Device-local position; pointer capture supports mouse, pen and touch without
// scrolling the page. A click after an actual drag must not open the dialog.
const positionKey='matclub-ai-position-v1';let position=null,drag=null,suppressClick=false;
try{const p=JSON.parse(localStorage.getItem(positionKey));if(p&&Number.isFinite(p.x)&&Number.isFinite(p.y))position={x:Math.max(0,Math.min(1,p.x)),y:Math.max(0,Math.min(1,p.y))}}catch{}
launch.title='Открыть помощника · Перетащи, чтобы переместить · Alt + стрелки';
function bounds(){const v=window.visualViewport,r=launch.getBoundingClientRect(),gap=8;return{left:(v?.offsetLeft||0)+gap,top:(v?.offsetTop||0)+gap,width:Math.max(0,(v?.width||innerWidth)-r.width-gap*2),height:Math.max(0,(v?.height||innerHeight)-r.height-gap*2)}}
function place(x,y,save=false){const b=bounds(),left=Math.max(b.left,Math.min(b.left+b.width,x)),top=Math.max(b.top,Math.min(b.top+b.height,y));launch.style.left=left+'px';launch.style.top=top+'px';launch.style.right='auto';launch.style.bottom='auto';if(save){position={x:b.width?(left-b.left)/b.width:0,y:b.height?(top-b.top)/b.height:0};try{localStorage.setItem(positionKey,JSON.stringify(position))}catch{}}}
function restorePosition(){if(!position||drag)return;const b=bounds();place(b.left+position.x*b.width,b.top+position.y*b.height)}
launch.addEventListener('pointerdown',e=>{if(!e.isPrimary||e.button!==0)return;suppressClick=false;const r=launch.getBoundingClientRect();drag={id:e.pointerId,x:e.clientX,y:e.clientY,left:r.left,top:r.top,moved:false};launch.setPointerCapture?.(e.pointerId)});
launch.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(!drag.moved&&Math.hypot(dx,dy)<6)return;drag.moved=true;launch.classList.add('ai-dragging');place(drag.left+dx,drag.top+dy);e.preventDefault()});
function endDrag(e){if(!drag||e.pointerId!==drag.id)return;const moved=drag.moved;drag=null;launch.classList.remove('ai-dragging');if(moved){const r=launch.getBoundingClientRect();place(r.left,r.top,true);suppressClick=e.type!=='pointercancel'}if(launch.hasPointerCapture?.(e.pointerId))launch.releasePointerCapture(e.pointerId)}
launch.addEventListener('pointerup',endDrag);launch.addEventListener('pointercancel',endDrag);launch.addEventListener('lostpointercapture',endDrag);
launch.addEventListener('keydown',e=>{if(!e.altKey)return;if(e.key==='Home'){e.preventDefault();position=null;launch.style.left='';launch.style.top='';launch.style.right='';launch.style.bottom='';try{localStorage.removeItem(positionKey)}catch{}return}const move={ArrowLeft:[-20,0],ArrowRight:[20,0],ArrowUp:[0,-20],ArrowDown:[0,20]}[e.key];if(move){e.preventDefault();const r=launch.getBoundingClientRect();place(r.left+move[0],r.top+move[1],true)}});
window.addEventListener('resize',restorePosition);window.visualViewport?.addEventListener('resize',restorePosition);window.visualViewport?.addEventListener('scroll',restorePosition);requestAnimationFrame(restorePosition);

launch.addEventListener('click',event=>{if(suppressClick&&event.detail!==0){suppressClick=false;return}suppressClick=false;if(!signedIn()){askForAccount();return}describe();if(!dialog.open){if(window.innerWidth<=767||document.querySelector('dialog[open]:not(#aiDialog)'))dialog.showModal();else dialog.show()}if(innerWidth>767)$('#aiInput').focus()});$('#aiClose').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{host();launch.focus()});dialog.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();dialog.close()}});$('#aiForm').addEventListener('submit',send);$('#aiContext').addEventListener('change',describe);$('#aiStop').addEventListener('click',()=>controller?.abort());$('#aiClear').addEventListener('click',()=>{if(history.length&&!confirm('Очистить переписку с помощником?'))return;history=[];dialog.classList.remove('ai-has-answer','ai-started');$('#aiMessages').replaceChildren();$('#aiStatus').textContent='Переписка очищена.'});dialog.querySelectorAll('[data-ai-prompt]').forEach(b=>b.addEventListener('click',()=>{$('#aiInput').value=b.dataset.aiPrompt;describe();$('#aiInput').focus()}));function reading(on){dialog.classList.toggle('ai-reading',on);$('#aiRead').setAttribute('aria-pressed',String(on));$('#aiRead').textContent=on?'К чату':'Читать';$('#aiReturn').hidden=!on}
$('#aiRead').addEventListener('click',()=>reading(!dialog.classList.contains('ai-reading')));$('#aiReturn').addEventListener('click',()=>{reading(false);$('#aiInput').focus()});$('#aiExpand').addEventListener('click',()=>{const on=dialog.classList.toggle('ai-expanded');$('#aiExpand').setAttribute('aria-pressed',String(on));$('#aiExpand').title=on?'Уменьшить окно':'Развернуть окно'});
$('#aiInput').addEventListener('keydown',event=>{if(event.key==='Enter'&&(event.ctrlKey||event.metaKey)){event.preventDefault();$('#aiForm').requestSubmit()}});
function viewport(){if(innerWidth<=767&&window.visualViewport){dialog.style.setProperty('--ai-vh',window.visualViewport.height+'px');dialog.style.setProperty('--ai-vtop',window.visualViewport.offsetTop+'px')}else{dialog.style.removeProperty('--ai-vh');dialog.style.removeProperty('--ai-vtop')}}window.visualViewport?.addEventListener('resize',viewport);window.visualViewport?.addEventListener('scroll',viewport);window.addEventListener('resize',viewport);dialog.addEventListener('toggle',viewport);viewport();
